const data = JSON.parse($json.output);

let response = data.answer || "";

if (Array.isArray(data.charts)) {

  for (const chartData of data.charts) {

    if (
      !chartData.labels ||
      !chartData.values ||
      chartData.labels.length === 0
    ) {
      continue;
    }

    const chart = {
      type: chartData.type || "bar",
      data: {
        labels: chartData.labels,
        datasets: [
          {
            label: chartData.title,
            data: chartData.values
          }
        ]
      },
      options: {
        plugins: {
          title: {
            display: true,
            text: chartData.title
          }
        }
      }
    };

    const chartUrl =
      `https://quickchart.io/chart?c=${encodeURIComponent(
        JSON.stringify(chart)
      )}&w=800&h=500`;

    response += `\n\n### ${chartData.title}\n\n`;
    response += `![${chartData.title}](${chartUrl})`;
  }
}

return [
  {
    json: {
      output: response
    }
  }
];
